58	/// Caches compiled re2 objects for given string patterns. Intended to support the common situation of a small set of patterns which are
59	/// evaluated over and over within the same query. In these situations, usage of the cache will save unnecessary pattern re-compilation.
60	/// However, we must be careful that caching does not add too much static overhead to overall pattern evaluation. Therefore, the cache is
61	/// intentionally very lightweight: a) no thread-safety/mutexes, b) small & fixed capacity, c) no collision list, d) but also no open
62	/// addressing, instead collisions simply replace the existing element.
63	class LocalCacheTable
64	{
65	public:
66	    using RegexpPtr = std::shared_ptr<Regexp>;
67	
68	    template <bool like, bool no_capture, bool case_insensitive>
69	    void getOrSet(const String & pattern, RegexpPtr & regexp)
70	    {
71	        StringAndRegexp & bucket = known_regexps[hasher(pattern) % max_regexp_cache_size];
72	
73	        if (likely(bucket.regexp != nullptr))
74	        {
75	            if (pattern == bucket.pattern)
76	                regexp = bucket.regexp;
77	            else
78	            {
79	                regexp = std::make_shared<Regexp>(createRegexp<like, no_capture, case_insensitive>(pattern));
80	                bucket = {pattern, regexp};
81	            }
82	        }
83	        else
84	        {
85	            regexp = std::make_shared<Regexp>(createRegexp<like, no_capture, case_insensitive>(pattern));
86	            bucket = {pattern, regexp};
87	        }
88	    }
89	
90	private:
91	    constexpr static size_t max_regexp_cache_size = 100; // collision probability
92	
93	    std::hash<std::string> hasher;
94	    struct StringAndRegexp
95	    {
96	        std::string pattern;
97	        RegexpPtr regexp;
98	    };
99	    using CacheTable = std::array<StringAndRegexp, max_regexp_cache_size>;
100	    CacheTable known_regexps;
