162	template <bool save_indices, bool WithEditDistance>
163	inline Regexps constructRegexps(const std::vector<String> & str_patterns, [[maybe_unused]] std::optional<UInt32> edit_distance)
164	{
165	    /// Common pointers
166	    std::vector<const char *> patterns;
167	    std::vector<unsigned int> flags;
168	
169	    /// Pointer for external edit distance compilation
170	    std::vector<hs_expr_ext> ext_exprs;
171	    std::vector<const hs_expr_ext *> ext_exprs_ptrs;
172	
173	    patterns.reserve(str_patterns.size());
174	    flags.reserve(str_patterns.size());
175	
176	    if constexpr (WithEditDistance)
177	    {
178	        ext_exprs.reserve(str_patterns.size());
179	        ext_exprs_ptrs.reserve(str_patterns.size());
180	    }
181	
182	    for (const StringRef ref : str_patterns)
183	    {
184	        patterns.push_back(ref.data);
185	        /* Flags below are the pattern matching flags.
186	         * HS_FLAG_DOTALL is a compile flag where matching a . will not exclude newlines. This is a good
187	         * performance practice according to Hyperscan API. https://intel.github.io/hyperscan/dev-reference/performance.html#dot-all-mode
188	         * HS_FLAG_ALLOWEMPTY is a compile flag where empty strings are allowed to match.
189	         * HS_FLAG_UTF8 is a flag where UTF8 literals are matched.
190	         * HS_FLAG_SINGLEMATCH is a compile flag where each pattern match will be returned only once. it is a good performance practice
191	         * as it is said in the Hyperscan documentation. https://intel.github.io/hyperscan/dev-reference/performance.html#single-match-flag
192	         */
193	        flags.push_back(HS_FLAG_DOTALL | HS_FLAG_SINGLEMATCH | HS_FLAG_ALLOWEMPTY | HS_FLAG_UTF8);
194	        if constexpr (WithEditDistance)
195	        {
196	            /// Hyperscan currently does not support UTF8 matching with edit distance.
197	            flags.back() &= ~HS_FLAG_UTF8;
198	            ext_exprs.emplace_back();
199	            /// HS_EXT_FLAG_EDIT_DISTANCE is a compile flag responsible for Levenstein distance.
200	            ext_exprs.back().flags = HS_EXT_FLAG_EDIT_DISTANCE;
201	            ext_exprs.back().edit_distance = edit_distance.value();
202	            ext_exprs_ptrs.push_back(&ext_exprs.back());
203	        }
204	    }
205	    hs_database_t * db = nullptr;
206	    hs_compile_error_t * compile_error;
207	
208	    std::unique_ptr<unsigned int[]> ids;
209	
210	    /// We mark the patterns to provide the callback results.
211	    if constexpr (save_indices)
212	    {
213	        ids.reset(new unsigned int[patterns.size()]);
214	        for (size_t i = 0; i < patterns.size(); ++i)
215	            ids[i] = i + 1;
216	    }
217	
218	    hs_error_t err;
219	    if constexpr (!WithEditDistance)
220	        err = hs_compile_multi(
221	            patterns.data(),
222	            flags.data(),
223	            ids.get(),
224	            patterns.size(),
225	            HS_MODE_BLOCK,
226	            nullptr,
227	            &db,
228	            &compile_error);
229	    else
230	        err = hs_compile_ext_multi(
231	            patterns.data(),
232	            flags.data(),
233	            ids.get(),
234	            ext_exprs_ptrs.data(),
235	            patterns.size(),
236	            HS_MODE_BLOCK,
237	            nullptr,
238	            &db,
239	            &compile_error);
240	
241	    if (err != HS_SUCCESS)
242	    {
243	        /// CompilerError is a unique_ptr, so correct memory free after the exception is thrown.
244	        CompilerError error(compile_error);
245	
246	        if (error->expression < 0)
247	            throw Exception(String(error->message), ErrorCodes::LOGICAL_ERROR);
248	        else
249	            throw Exception(
250	                "Pattern '" + str_patterns[error->expression] + "' failed with error '" + String(error->message),
251	                ErrorCodes::BAD_ARGUMENTS);
252	    }
253	
254	    ProfileEvents::increment(ProfileEvents::RegexpCreated);
255	
256	    /// We allocate the scratch space only once, then copy it across multiple threads with hs_clone_scratch
257	    /// function which is faster than allocating scratch space each time in each thread.
258	    hs_scratch_t * scratch = nullptr;
259	    err = hs_alloc_scratch(db, &scratch);
260	
261	    /// If not HS_SUCCESS, it is guaranteed that the memory would not be allocated for scratch.
262	    if (err != HS_SUCCESS)
263	        throw Exception("Could not allocate scratch space for hyperscan", ErrorCodes::CANNOT_ALLOCATE_MEMORY);
264	
265	    return {db, scratch};
266	}
