268	/// If WithEditDistance is False, edit_distance must be nullopt
269	/// Also, we use templates here because each instantiation of function
270	/// template has its own copy of local static variables which must not be the same
271	/// for different hyperscan compilations.
272	template <bool save_indices, bool WithEditDistance>
273	inline Regexps * get(const std::vector<std::string_view> & patterns, std::optional<UInt32> edit_distance)
274	{
275	    static Pool known_regexps; /// Different variables for different pattern parameters, thread-safe in C++11
276	
277	    std::vector<String> str_patterns;
278	    str_patterns.reserve(patterns.size());
279	    for (const auto & pattern : patterns)
280	        str_patterns.emplace_back(std::string(pattern.data(), pattern.size()));
281	
282	    /// Get the lock for finding database.
283	    std::unique_lock lock(known_regexps.mutex);
284	
285	    auto it = known_regexps.storage.find({str_patterns, edit_distance});
286	
287	    /// If not found, compile and let other threads wait.
288	    if (known_regexps.storage.end() == it)
289	    {
290	        it = known_regexps.storage
291	                 .emplace(std::piecewise_construct, std::make_tuple(std::move(str_patterns), edit_distance), std::make_tuple())
292	                 .first;
293	        it->second.setConstructor([&str_patterns = it->first.first, edit_distance]()
294	        {
295	            return constructRegexps<save_indices, WithEditDistance>(str_patterns, edit_distance);
296	        });
297	    }
298	
299	    /// Unlock before possible construction.
300	    lock.unlock();
301	    return it->second();
302	}
303	
