27	/// Thread-safe cache that evicts entries which are not used for a long time.
28	/// WeightFunction is a functor that takes Mapped as a parameter and returns "weight" (approximate size)
29	/// of that value.
30	/// Cache starts to evict entries when their total weight exceeds max_size.
31	/// Value weight should not change after insertion.
32	template <typename TKey, typename TMapped, typename HashFunction = std::hash<TKey>, typename WeightFunction = TrivialWeightFunction<TMapped>>
33	class LRUCache
34	{
35	public:
36	    using Key = TKey;
37	    using Mapped = TMapped;
