80	    /// If the value for the key is in the cache, returns it. If it is not, calls load_func() to
81	    /// produce it, saves the result in the cache and returns it.
82	    /// Only one of several concurrent threads calling getOrSet() will call load_func(),
83	    /// others will wait for that call to complete and will use its result (this helps prevent cache stampede).
84	    /// Exceptions occurring in load_func will be propagated to the caller. Another thread from the
85	    /// set of concurrent threads will then try to call its load_func etc.
86	    ///
87	    /// Returns std::pair of the cached value and a bool indicating whether the value was produced during this call.
88	    template <typename LoadFunc>
89	    std::pair<MappedPtr, bool> getOrSet(const Key & key, LoadFunc && load_func)
90	    {
91	        InsertTokenHolder token_holder;
92	        {
93	            std::lock_guard cache_lock(mutex);
94	
95	            auto val = getImpl(key);
96	            if (val)
97	            {
